    if (ch == 2) {
        payload = 2 * bps;
        payload = payload + 1;
        payload = payload * blocksize;
    } else {
        payload = ch * bps;
        payload = payload * blocksize;
    }
    payload = payload + 7;
    payload = payload / 8;
    count = count + payload;
    count = count + 2;
    return count;
}
